# Summary of evidence:
# L0H0_ATTN: attention at pos 2 → pos 1 (w≈0.90), pos 5 → pos 4 (w≈0.74-0.82)
#   Always attends to i-1 (positional selection). Write vectors at dup positions
#   with different prev tokens: cos(dup-a,dup-b)=-0.40, cos(dup-a,dup-c)=0.63
#   These are far from 1.0 → writes encode WHICH token, not just dup-status → ROUTER
#
# L0_MLP: ablated → predictions collapse (r4). Receives ONE residual vector per
#   position and transforms it into class prediction (non-binary) → MAPPER

submission = {
    "tags": {
        "L0H0_ATTN": "ROUTER",
        "L0_MLP": "MAPPER"
    },
    "evidence": {
        "L0H0_ATTN": {
            "hypothesis": "Attends to position i-1 via positional index-based selection and routes the previous token's value vector to the current position; write vectors at dup positions with different previous tokens have cosines ranging from -0.40 to 0.63 (not near 1), confirming the write encodes which previous token was present rather than a binary dup flag.",
            "test": "r2",
            "supports": True
        },
        "L0_MLP": {
            "hypothesis": "Transforms the residual stream independently at each position (single input vector) into a non-binary class output; it reads the combined residual containing both current token and routed previous token information and outputs the dedup classification.",
            "test": "r4",
            "supports": True
        }
    }
}

with open('/work/submission.json', 'w') as f:
    json.dump(submission, f, indent=2)
print(json.dumps(submission, indent=2))

